<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { studio, edit, addScene } from '../stores/project-store';
import { roadwayPreset, validateBandMapping } from '../../../../packages/story-core/src/roadway-animation';
import { solveRoadwayWidths } from '../../../../packages/story-core/src/roadway';
import type { Roadway, RoadwayCrossSection, RoadwayDimension, ProjectDocument } from '../../../../packages/project-schema/src/index';
const evidenceOpen = ref(false), evidenceTarget = ref<number | 'curb' | 'envelope'>('curb');
const evidence = ref({ status: 'assumed', value: 1, unit: 'm', rationale: '', sourceIds: [] as string[], date: '', location: '', method: '', uncertainty: '' });
const endpoint = ref<'start'|'end'>('start');
const segmentId = ref(''), role = ref<'existing'|'proposed'>('proposed'), units = ref<'m'|'ft'>('m'), raw = ref(''), advanced = ref(false);
const scene = computed(() => studio.document!.scenes.find(s => s.id === studio.selectedSceneId)!);
const road = computed(() => studio.document!.roadways?.find(r => r.id === scene.value.roadway?.roadwayId));
const segment = computed(() => road.value?.segments.find(s => s.id === segmentId.value) ?? road.value?.segments[0]);
function resolve(r: Roadway, value: Roadway['segments'][number]['existing']): RoadwayCrossSection { return 'layoutId' in value ? r.layouts!.find(l => l.id === value.layoutId)!.section : value; }
function editableSection(r: Roadway, s: Roadway['segments'][number]) { const end = endpoint.value === 'end' ? s.transition?.[role.value === 'existing' ? 'existingLayoutId' : 'proposedLayoutId'] : undefined; return end ? resolve(r, { layoutId: end }) : resolve(r, s[role.value]); }
const section = computed(() => road.value && segment.value ? editableSection(road.value, segment.value) : undefined);
const balance = computed(() => section.value ? solveRoadwayWidths(JSON.parse(JSON.stringify(section.value))) : null);
const mapping = computed(() => scene.value.roadway?.mappings[segment.value?.id ?? ''] ?? []);
const options = (side: 'existing'|'proposed') => road.value && segment.value ? resolve(road.value, segment.value[side]).bands.map(b => ({ label: (b.label ?? b.kind) + ' · ' + b.id, value: b.id })) : [];
const mappingError = computed(() => { if (!road.value || !segment.value) return ''; try { validateBandMapping(resolve(road.value, segment.value.existing).bands, resolve(road.value, segment.value.proposed).bands, mapping.value); return ''; } catch (e) { return String(e); } });
function change(fn: (r: Roadway, s: Roadway['segments'][number], section: RoadwayCrossSection, p: ProjectDocument) => void) { try { edit(p => { const r = p.roadways!.find(r => r.id === road.value!.id)!, s = r.segments.find(s => s.id === segment.value!.id)!; fn(r,s,editableSection(r,s),p); }); } catch (e) { studio.error = String(e); } }
function create() { try {
  const p = studio.document!, feature = p.features.find(f => f.id === studio.selectedFeatureId);
  if (!feature || feature.kind !== 'line') throw new Error('Select an imported corridor line before adding a roadway.');
  const geometry = p.featureRevisions.find(r => r.id === feature.currentRevisionId)!.geometry, preset = roadwayPreset(feature.currentRevisionId, crypto.randomUUID());
  addScene(geometry, feature.currentRevisionId);
  edit(d => { d.roadways ??= []; d.roadways.push(preset.roadway); const s = d.scenes.find(s => s.id === studio.selectedSceneId)!; s.title = 'Roadway concept'; s.caption = 'Illustrative four-to-three concept — dimensions are assumptions'; s.roadway = { roadwayId: preset.roadway.id, startFrame: 15, endFrame: s.durationFrames-16, mappings: preset.mappings }; });
} catch (e) { studio.error = String(e); } }
const assumed = (value: number): RoadwayDimension => ({ status: 'assumed', value, unit: units.value, meters: value * (units.value === 'ft' ? .3048 : 1), rationale: 'Manual concept dimension; replace with sourced evidence.' });
function width(index: number, value: string) { change((_r,_s,c) => { if (c.bands[index].locked) throw new Error('Unlock this width before editing.'); c.bands[index].width = assumed(Number(value)); }); }
function dimension(value: RoadwayDimension): string { return value.status === 'unknown' ? '' : (value.meters / (units.value === 'ft' ? .3048 : 1)).toFixed(2); }
function addBand() { change((_r,_s,c) => c.bands.push({ id: crypto.randomUUID(), kind: 'buffer', direction: 'none', location: 'between-curbs', locked: false, width: assumed(1) })); }
function split() { change((r,s,_c,p) => { const midpoint = (s.startMeters+s.endMeters)/2, next = JSON.parse(JSON.stringify(s)); next.id = crypto.randomUUID(); next.name = s.name + ' · second half'; next.startMeters = midpoint; s.endMeters = midpoint; r.segments.splice(r.segments.indexOf(s)+1,0,next);
  for (const scene of p.scenes) if (scene.roadway?.roadwayId === r.id) scene.roadway.mappings[next.id] = JSON.parse(JSON.stringify(scene.roadway.mappings[s.id]));
}); }
function updateMapping(index: number, field: 'existingId'|'proposedId', value: string | null) { try { edit(p => { const slot = p.scenes.find(s => s.id === studio.selectedSceneId)!.roadway!.mappings[segment.value!.id][index]; if (value) slot[field] = value; else delete slot[field]; }); } catch (e) { studio.error = String(e); } }
function newSlot() { try { edit(p => p.scenes.find(s => s.id === studio.selectedSceneId)!.roadway!.mappings[segment.value!.id].push({ id: crypto.randomUUID(), existingId: options('existing')[0]?.value })); } catch(e) { studio.error = String(e); } }
watch(advanced, value => { if (value) raw.value = JSON.stringify(road.value, null, 2); });
function applyData() { change((r,_s,_c,p) => { const next = JSON.parse(raw.value); if (next.id !== r.id) throw new Error('Keep the roadway identity unchanged.'); p.roadways![p.roadways!.indexOf(r)] = next; }); }
function taper(enabled: boolean) { change((r,s) => { if (!enabled) { delete s.transition; endpoint.value = 'start'; return; } r.layouts ??= []; const existingId = crypto.randomUUID(), proposedId = crypto.randomUUID(); r.layouts.push({ id: existingId, section: JSON.parse(JSON.stringify(resolve(r,s.existing))) }, { id: proposedId, section: JSON.parse(JSON.stringify(resolve(r,s.proposed))) }); s.transition = { existingLayoutId: existingId, proposedLayoutId: proposedId }; }); }
function openEvidence(target: number | 'curb' | 'envelope') {
  evidenceTarget.value = target;
  const dimension = target === 'curb' ? section.value!.curbToCurb : target === 'envelope' ? section.value!.envelope.width : section.value!.bands[target].width;
  evidence.value = { status: dimension.status, value: 1, unit: 'm', rationale: '', sourceIds: [], date: '', location: '', method: '', uncertainty: '', ...JSON.parse(JSON.stringify(dimension)) }; evidenceOpen.value = true;
}
function applyEvidence() { change((r,_s,section) => {
  const e = evidence.value, mode = e.status;
  const dimension: RoadwayDimension = mode === 'unknown' ? { status: 'unknown' } : mode === 'assumed' ? { status: 'assumed', value: e.value, unit: e.unit as 'm'|'ft', meters: e.value * (e.unit === 'ft' ? .3048 : 1), rationale: e.rationale } : { status: mode as 'documented'|'estimated', value: e.value, unit: e.unit as 'm'|'ft', meters: e.value * (e.unit === 'ft' ? .3048 : 1), sourceIds: e.sourceIds, date: e.date, location: e.location, method: e.method, uncertainty: e.uncertainty };
  const target = evidenceTarget.value;
  if (target === 'curb') section.curbToCurb = dimension; else if (target === 'envelope') section.envelope.width = dimension; else { if (section.bands[target].locked) throw new Error('Unlock the dimension before changing its evidence.'); section.bands[target].width = dimension; }
  if (mode === 'estimated' || mode === 'documented') r.sourceIds = [...new Set([...r.sourceIds,...e.sourceIds])];
}); if (!studio.error) evidenceOpen.value = false; }
const kinds = ['through-lane','center-turn-lane','bike-lane','buffer','sidewalk','parking','median','other'];
</script>
<template><div class="inspector-body"><div class="eyebrow">Roadway studio</div><h3>Make the space visible</h3><p class="hint">A concept explains how width changes. It does not establish an adopted design or engineering feasibility.</p>
<q-btn v-if="!road" color="primary" label="Add four-to-three concept" @click="create" />
<template v-else><q-input :model-value="road.title" outlined dense label="Roadway title" @update:model-value="v => change(r => r.title = String(v))" />
<q-select v-model="segmentId" :options="road.segments.map(s => ({ label: s.name, value: s.id }))" emit-value map-options outlined dense label="Segment" :display-value="segment?.name" />
<q-input :model-value="road.stationOrigin" dense outlined label="Station origin" @change="e => change(r => r.stationOrigin = e.target.value)" /><q-input :model-value="road.stationDirection" dense outlined label="Increasing station direction" @change="e => change(r => r.stationDirection = e.target.value)" /><p class="hint">Station increases downward in the schematic. Left and right are viewed looking along that direction.</p>
<q-input :model-value="segment?.name" dense outlined label="Segment name" @update:model-value="v => change((_r,s) => s.name = String(v))" /><q-input :model-value="road.stationExtentMeters" dense type="number" label="Corridor extent (meters)" @change="e => change(r => r.stationExtentMeters = Number(e.target.value))" /><div class="button-row"><q-btn outline size="sm" label="Split segment" @click="split" /><q-btn-toggle v-model="units" dense flat :options="[{ label: 'm', value: 'm' }, { label: 'ft', value: 'ft' }]" /></div>
<div v-if="segment" class="form-grid"><q-input :model-value="segment.startMeters" type="number" dense label="From (meters)" @change="e => change((_r,s) => s.startMeters = Number(e.target.value))" /><q-input :model-value="segment.endMeters" type="number" dense label="Through (meters)" @change="e => change((_r,s) => s.endMeters = Number(e.target.value))" /></div>
<q-btn-toggle v-model="role" spread unelevated :options="[{ label: 'Existing', value: 'existing' }, { label: 'Proposed', value: 'proposed' }]" />
<q-checkbox :model-value="!!segment?.transition" label="Taper widths along this segment" @update:model-value="taper" /><q-btn-toggle v-if="segment?.transition" v-model="endpoint" dense :options="[{label: 'Start section',value: 'start'}, {label: 'End section',value: 'end'}]" /><div v-if="section" class="section-stack"><div class="form-grid"><q-input :model-value="dimension(section.curbToCurb)" type="number" dense label="Curb to curb" @change="e => change((_r,_s,c) => c.curbToCurb = assumed(Number(e.target.value)))" /><q-input :model-value="dimension(section.envelope.width)" type="number" dense label="Illustrated envelope" @change="e => change((_r,_s,c) => c.envelope.width = assumed(Number(e.target.value)))" /></div>
<div class="button-row"><q-btn flat dense size="sm" label="Curb evidence" @click="openEvidence('curb')" /><q-btn flat dense size="sm" label="Envelope evidence" @click="openEvidence('envelope')" /></div><div class="notice" :class="balance?.status === 'infeasible' ? 'warn' : 'good'"><strong>{{ balance?.status === 'feasible' ? 'Width budget balanced' : 'Resolve width budget' }}</strong><div v-for="d in balance?.diagnostics" :key="d.code + d.constraint">{{ d.message }} {{ d.residualMeters === null ? '' : '(' + d.residualMeters.toFixed(2) + ' m)' }}</div></div>
<div v-for="(band, i) in section.bands" :key="band.id" class="mini-card"><div class="form-grid"><q-select :model-value="band.kind" dense :options="kinds" label="Band" @update:model-value="v => change((_r,_s,c) => c.bands[i].kind = v)" /><q-input :model-value="dimension(band.width)" :disable="band.locked" dense type="number" step=".1" :label="'Width (' + units + ')'" @change="e => width(i, e.target.value)" /><q-select :model-value="band.direction" dense :options="['forward','reverse','both','none']" label="Direction" @update:model-value="v => change((_r,_s,c) => c.bands[i].direction = v)" /><q-select :model-value="band.location" dense :options="['between-curbs','outside-curbs']" label="Location" @update:model-value="v => change((_r,_s,c) => c.bands[i].location = v)" /></div><div class="button-row"><q-checkbox :model-value="band.locked" label="Lock width" dense @update:model-value="v => change((_r,_s,c) => c.bands[i].locked = v)" /><q-btn flat dense size="sm" :label="band.width.status + ' evidence'" :disable="band.locked" @click="openEvidence(i)" /><q-btn flat size="sm" label="Remove" :disable="band.locked" @click="change((_r,_s,c) => c.bands.splice(i, 1))" /></div></div><q-btn outline size="sm" label="Add band" @click="addBand" /></div>
<q-expansion-item label="Reallocation mapping"><div class="section-stack"><p class="hint">Each endpoint band appears once, in left-to-right order. A blank side means a band enters or leaves.</p><div v-for="(slot, i) in mapping" :key="slot.id" class="mini-card"><div class="form-grid"><q-select :model-value="slot.existingId" dense clearable label="Existing" emit-value map-options :options="options('existing')" @update:model-value="v => updateMapping(i, 'existingId', v)" /><q-select :model-value="slot.proposedId" dense clearable label="Proposed" emit-value map-options :options="options('proposed')" @update:model-value="v => updateMapping(i, 'proposedId', v)" /></div><q-btn flat size="sm" label="Remove slot" @click="change((_r,_s,_c,p) => p.scenes.find(s => s.id === studio.selectedSceneId)!.roadway!.mappings[segment!.id].splice(i, 1))" /></div><q-btn outline size="sm" label="Add mapping slot" @click="newSlot" /><p v-if="mappingError" class="error">{{ mappingError }}</p></div></q-expansion-item>
<q-expansion-item v-model="advanced" label="Evidence & shared layouts"><div class="section-stack"><p class="hint">Record source-backed widths, dates, uncertainty, segment gaps, and longitudinal transitions. Refer to source IDs from the library.</p><q-input v-model="raw" outlined type="textarea" rows="18" input-class="code-input" /><q-btn outline label="Apply roadway data" @click="applyData" /></div></q-expansion-item>
</template>
<q-dialog v-model="evidenceOpen"><q-card class="dialog-card"><q-card-section><h2>Dimension evidence</h2><p>Record what supports this width. An assumption stays labeled as illustrative.</p><div class="form-grid"><q-select v-model="evidence.status" outlined dense label="Evidence status" :options="['unknown','assumed','estimated','documented']" /><q-select v-model="evidence.unit" outlined dense label="Original units" :options="['m','ft']" /><q-input v-if="evidence.status !== 'unknown'" v-model.number="evidence.value" type="number" outlined dense label="Original value" /><q-input v-if="evidence.status === 'assumed'" v-model="evidence.rationale" outlined dense label="Assumption rationale" /><template v-if="['estimated','documented'].includes(evidence.status)"><q-select v-model="evidence.sourceIds" class="full" :options="studio.document!.sources.map(s => ({label:s.title,value:s.id}))" multiple emit-value map-options outlined dense label="Retained source records" /><q-input v-model="evidence.date" type="date" stack-label outlined dense label="Evidence date" /><q-input v-model="evidence.location" outlined dense label="Measurement location" /><q-input v-model="evidence.method" class="full" outlined dense label="Measurement or estimation method" /><q-input v-model="evidence.uncertainty" class="full" outlined dense label="Uncertainty and limits" /></template></div><p v-if="studio.error" class="error">{{ studio.error }}</p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup /><q-btn color="primary" label="Apply evidence" @click="applyEvidence" /></q-card-actions></q-card></q-dialog>
</div></template>
